using System;
using System.Linq;
using System.Collections.Generic;
using System.Text;
public static class ForgeCoolingChecks {
 static void Require(bool c,string m){if(!c)throw new Exception(m);}
 static ForgeMvp.Piece Blade(ForgeCoolingGraph graph=null)=>new ForgeMvp.Piece{id=17,material=1,heat=900,shaped=true,data=new ForgeItemData{cooling=graph??ForgeCoolingGraph.Tutorial()}};
 static ForgeRunContext Context(ForgeMvp.Piece b,BlueprintObservation o=null,bool unlocked=true)=>new ForgeRunContext{PracticeBlade=b,CoolingUnlocked=unlocked,Observation=o};
 static ForgeMvp.Evaluation Eval(ForgeMvp.Piece b,string code,long stock=1000,BlueprintObservation o=null,bool unlocked=true)=>BlueprintRuntime.Evaluate(code,0,0,"test",1,new Dictionary<int,long>{{8,stock}},context:Context(b,o,unlocked));
 static void Ok(ForgeMvp.Evaluation e)=>Require(e.error==null,e.error);
 static int Used(ForgeMvp.Evaluation e)=>e.steps.Sum(s=>s.consumed!=null&&s.consumed.TryGetValue(8,out int n)?n:0);
 static string Graph(ForgeCoolingGraph g)=>string.Join(",",Enumerable.Range(0,g.Count).SelectMany(a=>Enumerable.Range(0,g.Count).Select(b=>g.Cost(a,b))));
 static int Optimum(ForgeCoolingGraph g){var d=new int[g.Count,g.Count];for(int a=0;a<g.Count;a++)for(int b=0;b<g.Count;b++)d[a,b]=a==b?0:g.Cost(a,b)>0?g.Cost(a,b):1000000;for(int k=0;k<g.Count;k++)for(int a=0;a<g.Count;a++)for(int b=0;b<g.Count;b++)d[a,b]=Math.Min(d[a,b],d[a,k]+d[k,b]);return d[g.Start,g.End];}
 static void Drain(BlueprintRuntime.Session s){int i=0;while(!s.Completed){Require(++i<10000,"step test bound");s.Advance().GetAwaiter().GetResult();foreach(var step in s.Evaluation.steps)step.ReleaseCooling();}}
 public static string Run(){var log=new StringBuilder();int count=0;Action<string,Action> test=(name,action)=>{action();count++;log.AppendLine("PASS "+name);};
 test("80-84 registered without collisions; prerequisites restored from saved nodes",()=>{foreach(int n in Enumerable.Range(80,5))Require(BlueprintAliases.All.Count(a=>a.Symbol==n.ToString())==1,"alias "+n);var tech=new ForgeTechnology();Require(!BlueprintResearchGuide.FeatureVisible(BlueprintFeature.CoolingCount,tech,null),"hidden locked guide");tech.Restore(Array.Empty<BlueprintFeature>(),new[]{"material-8"});Require(tech.MaterialAvailable(8)&&BlueprintResearchGuide.FeatureVisible(BlueprintFeature.CoolingCount,tech,null),"restored unlock");var locked=new ForgeTechnology();var e=BlueprintRuntime.Evaluate("p=1(1)\n80(p)",0,1,"test",1,technology:locked,context:new ForgeRunContext{CoolingUnlocked=true});Require(e.error!=null&&e.steps.Count==0,"real technology cannot bypass with context");});
 test("5000 generated graphs are symmetric positive connected bounded and independently cloned",()=>{for(int n=4;n<=8;n++)for(uint seed=0;seed<1000;seed++){var g=ForgeCoolingGraph.Create(seed,new ForgeCoolingSettings{points=n,minimumCost=2,maximumCost=9});Require(g.Count==n&&g.Start!=g.End,"endpoints");for(int a=0;a<n;a++){Require(g.Cost(a,a)==-1,"self edge");for(int b=0;b<n;b++)Require(g.Cost(a,b)==g.Cost(b,a)&&(g.Cost(a,b)==-1||g.Cost(a,b)>=2&&g.Cost(a,b)<=9),"edge invariants");}Require(Optimum(g)<1000000&&g.PathCost(g.DefaultPath())>0,"connected and legacy route");var clone=g.Clone();Require(!ReferenceEquals(g,clone)&&Graph(g)==Graph(clone),"deep clone");}});
 test("tutorial paths consume 11 and 6, revisits consume every edge",()=>{foreach(var example in new[]{new{Path="[0,1,3]",Cost=11},new{Path="[0,2,3]",Cost=6},new{Path="[0,1,0,2,3]",Cost=10}}){var b=Blade();var e=Eval(b,"84(Blade, 8, "+example.Path+")");Ok(e);Require(Used(e)==example.Cost&&e.steps.Single().coolingCost==example.Cost,"actual sum");Require(b.heat==0&&b.data.frost&&!b.data.cracked,"existing cooling effect");Require(e.steps.Single().process==4&&Math.Abs(e.steps.Single().duration-.8)<.0001,"existing animation receipt");}});
 test("queries do not spend inventory, reroll or alter heat; missing/self edge return minus one",()=>{var b=Blade();string before=Graph(b.data.cooling);var e=Eval(b,"n=80(Blade)\ns=81(Blade)\ne=82(Blade)\nx=83(Blade, 0, 3)\ny=83(Blade, 1, 1)",0);Ok(e);Require((int)e.values["n"]==4&&(int)e.values["s"]==0&&(int)e.values["e"]==3&&(int)e.values["x"]==-1&&(int)e.values["y"]==-1,"query values");Require(Used(e)==0&&e.steps.All(s=>s.duration==0)&&b.heat==900&&Graph(b.data.cooling)==before,"read only");Require(e.steps[3].coolingA==0&&e.steps[3].coolingB==3&&e.steps[3].text.Contains("연결 없음"),"missing edge highlight");});
 test("invalid paths types ranges arities stock and object state fail atomically at correct line",()=>{
 foreach(string call in new[]{"80()","81(Blade,0)","82(0)","83(Blade,0)","83(Blade,-1,0)","83(Blade,4,0)","83(Blade,True,0)","84(Blade,3,[0,2,3])","84(Blade,8,0)","84(Blade,8,[])","84(Blade,8,[0])","84(Blade,8,[1,3])","84(Blade,8,[0,2])","84(Blade,8,[0,3])","84(Blade,8,[0,0,2,3])","84(Blade,8,[0,5,3])","84(Blade,8,[0,True,3])"}){
 var b=Blade();string graph=Graph(b.data.cooling);var e=Eval(b,"x=0\n"+call);Require(e.error!=null&&e.errorLine==2,call+" line");Require(b.heat==900&&!b.data.frost&&!b.coolingBusy&&Used(e)==0&&Graph(b.data.cooling)==graph,call+" atomic");}
 var poor=Blade();var p=Eval(poor,"84(Blade,8,[0,2,3])",5);Require(p.error!=null&&Used(p)==0&&poor.heat==900,"stock atomic");
 foreach(int kind in new[]{0,1,2}){var b=Blade();if(kind==0)b.shaped=false;if(kind==1)b.material=2;if(kind==2)b.data.recovered=true;var e=Eval(b,"84(Blade,8,[0,2,3])");Require(e.error!=null&&Used(e)==0&&b.heat==900,"object atomic");}
 var longPath=string.Join(",",Enumerable.Range(0,128).Select(i=>(i%2).ToString()).Concat(new[]{"3"}));var tooLong=Eval(Blade(),"84(Blade,8,["+longPath+"])");Require(tooLong.error!=null&&Used(tooLong)==0,"path length bound");
 });
 test("locked runtime and legacy cooling cannot bypass unlock or path cost",()=>{foreach(string code in new[]{"80(Blade)","83(Blade,0,1)","84(Blade,8,[0,2,3])","4(Blade,8)"}){var b=Blade();var e=Eval(b,code,100,unlocked:false);Require(e.error!=null&&Used(e)==0&&b.heat==900,"locked "+code);}var legacy=Eval(Blade(),"4(Blade,8)");Ok(legacy);Require(Used(legacy)==11,"legacy basic path cost");});
 test("busy cooling rejects duplicate overlapping execution and releases on disposal",()=>{var b=Blade();using(var session=BlueprintRuntime.StartSession("84(Blade,8,[0,2,3])\nx=1",0,0,materialStocks:new Dictionary<int,long>{{8,100}},context:Context(b))){session.Advance().GetAwaiter().GetResult();Require(b.coolingBusy&&session.MaterialCount(8)==94,"in flight debit once");var duplicate=Eval(b,"84(Blade,8,[0,2,3])");Require(duplicate.error!=null&&Used(duplicate)==0,"busy rejected");session.Dispose();Require(!b.coolingBusy,"cancel releases");}});
 test("cold recooling follows previous crack rule and never stacks frost bonus",()=>{var b=Blade();Ok(Eval(b,"84(Blade,8,[0,2,3])"));var first=new ForgeProduct("x",b.heat,b.shaped,b.traits,0,0,1,b.data);Ok(Eval(b,"84(Blade,8,[0,2,3])"));var second=new ForgeProduct("x",b.heat,b.shaped,b.traits,0,0,1,b.data);Require(b.data.cracked&&ForgePricing.Bonuses(first)["서리 문양"]==ForgePricing.Bonuses(second)["서리 문양"],"single existing bonus");});
 test("actual numeric Dijkstra example cools all graph sizes at reference minimum cost",()=>{for(int n=4;n<=8;n++)for(uint seed=1;seed<=15;seed++){var graph=ForgeCoolingGraph.Create(seed,new ForgeCoolingSettings{points=n});var b=Blade(graph);var e=Eval(b,ForgeCoolingGuide.Algorithm);Ok(e);Require(Used(e)==Optimum(graph),"shortest path n="+n+" seed="+seed);Require(b.heat==0&&b.data.frost,"completed");}var tutorial=Eval(Blade(),ForgeCoolingGuide.Algorithm);Ok(tutorial);Require(Used(tutorial)==6,"teaching example minimum");});
 test("full in-game guide example creates actual product and separate blades own graphs",()=>{var e=BlueprintRuntime.Evaluate(ForgeCoolingGuide.FullExample,0,1,"guide",7,new Dictionary<int,long>{{8,1000}},context:new ForgeRunContext{CoolingUnlocked=true});Ok(e);Require(e.product!=null&&e.product.Data.frost&&Used(e)==Optimum(e.product.Data.cooling),"full example");var pair=BlueprintRuntime.Evaluate("a=1(1)\nb=1(1)",0,2,"two",1);Ok(pair);var a=(ForgeMvp.Piece)pair.values["a"];var b=(ForgeMvp.Piece)pair.values["b"];Require(!ReferenceEquals(a.data.cooling,b.data.cooling),"separate instances");});
 test("observation records actual values once and preserves short-circuit execution",()=>{string code="333 f(p):\n    << 83(p,0,1)\nX=[11,11,11,11]\nCandidate=f(Blade)\n1?(Candidate < 5):\n    X[3]=Candidate\n1?(False and 83(Blade,99,0) > 0):\n    X[0]=99";var on=new BlueprintObservation{Enabled=true};var off=new BlueprintObservation();var a=Eval(Blade(),code,o:on);var b=Eval(Blade(),code,o:off);Ok(a);Ok(b);Require(a.steps.Count==1&&b.steps.Count==1,"call evaluated once");Require(on.History.Contains("2 < 5 → 참")&&on.History.Contains("X[3] 변경 11 → 2")&&on.History.Contains("오른쪽 평가 생략"),"recorded operands and changes");Require(off.RecordCount==0,"disabled no logging");Require(on.Names.Contains("X")&&!on.Names.Contains("Distance"),"actual names");Require(on.BindArray("X",4,out var array,out _)&&array[3]==2,"binding actual values");});
 test("binding resolves reassignments bad lengths bad types and vanished scopes safely",()=>{var observer=new BlueprintObservation{Enabled=true};var scope=new Dictionary<string,object>{{"Custom",new List<int>{9,-7,999,1}}};observer.Scope(1,null,scope,scope);Require(observer.BindArray("Custom",4,out var a,out _)&&a[1]==-7&&a[2]==999,"wrong player values unchanged");scope["Custom"]=new[]{4,3,2,1};Require(observer.BindArray("Custom",4,out var b,out _)&&b[0]==4&&!ReferenceEquals(a,b),"reassigned binding");scope["Custom"]=new[]{1};Require(!observer.BindArray("Custom",4,out _,out string reason)&&reason.Contains("길이"),"length reason");scope["Custom"]=42;Require(!observer.BindArray("Custom",4,out _,out reason)&&reason.Contains("정수 배열"),"type reason");scope.Remove("Custom");Require(!observer.BindArray("Custom",4,out _,out reason)&&reason.Contains("기록"),"missing binding");for(int i=0;i<1000;i++)observer.Record(i,null,"test");Require(observer.RecordCount==80,"bounded history");});
 test("named index failure includes source line and valid range",()=>{var e=Eval(Blade(),"Custom=[0,0,0,0]\nx=Custom[4]");Require(e.errorLine==2&&e.error.Contains("Custom[4]")&&e.error.Contains("0~3"),"index diagnostic");});
 test("breakpoints continue once then stop on later visit; stepping does not duplicate statements",()=>{var bp=new BlueprintBreakpoints();bp.Toggle(null,2);Require(bp.StopBefore(null,2,false)&&!bp.StopBefore(null,2,false)&&bp.StopBefore(null,2,false),"continue skip once");Require(!bp.StopBefore(null,2,true),"explicit step");using(var s=BlueprintRuntime.StartSession("x=0\n888(x < 3):\n    x=x+1",0,0)){Drain(s);Ok(s.Evaluation);Require((int)s.Evaluation.values["x"]==3,"three increments");}});
 test("practice clones stock and blade, freezes clock, reset cancels queued old state",()=>{var original=Blade();var before=Graph(original.data.cooling);using(var p=new ForgeCoolingPractice(original,11,true)){var s=p.Start("84(Blade,8,[0,2,3])\nx=1");s.Advance().GetAwaiter().GetResult();Require(p.Spent==6&&p.Blade.heat==0&&original.heat==900,"isolated practice");var old=p.Blade;uint generation=p.Generation;p.Reset();Require(s.Cancelled&&generation!=p.Generation&&p.Spent==0&&p.Remaining==11&&p.Session==null&&p.Observation.RecordCount==0,"reset stats/cancel");Require(p.Blade.heat==900&&Graph(p.Blade.data.cooling)==before&&p.Blade!=old,"same graph restored");s.Advance().GetAwaiter().GetResult();old.heat=99;Require(p.Blade.heat==900&&original.heat==900,"old work isolated");}});
 test("view clears stale target/path and ignores late animation generation",()=>{var view=new ForgeCoolingViewState();view.Select(Blade());uint old=view.Generation;view.Path=new[]{0,2,3};view.A=2;view.Clear();view.Animate(old,.5f);Require(view.Blade==null&&view.Path==null&&view.A==-1&&view.Progress==1,"late ignored");var b=Blade();b.id=99;view.Select(b);view.Animate(old,.7f);Require(view.Blade.id==99&&view.Progress==1,"new target safe");});
 test("legacy saved products receive stable independent graphs and never reroll on read",()=>{var a=new ForgeProduct("old save",0,true,ForgeTraits.None,0,0,1);var b=new ForgeProduct("old save",0,true,ForgeTraits.None,0,0,1);Require(Graph(a.Data.cooling)==Graph(b.Data.cooling),"stable migration");Require(!ReferenceEquals(a.Data.cooling,b.Data.cooling),"separate data");for(int i=0;i<20;i++)Require(Graph(a.Data.cooling)==Graph(b.Data.cooling),"stable read");});
 test("long array slice append and pop report actual changed indices",()=>{var observation=new BlueprintObservation{Enabled=true};var e=Eval(Blade(),"A=[]\n123(i in 45):\n    301(A,i)\nA[40:42]=[99,98]\nx=302(A)",o:observation);Ok(e);Require(observation.History.Contains("A[40] 슬라이스 변경 40 → 99")&&observation.History.Contains("A[41] 슬라이스 변경 41 → 98")&&observation.History.Contains("A[44] 제거: 44 → 없음"),"real tail changes");});
 test("schematic cost labels do not overlap each other or node data at 4-8 points",()=>{for(int n=4;n<=8;n++){var g=ForgeCoolingGraph.Create(3,new ForgeCoolingSettings{points=n});var reserved=new List<UnityEngine.Rect>();UnityEngine.Rect Box(UnityEngine.Vector2 p,float w,float h)=>new UnityEngine.Rect(p.x*660-w/2,p.y*680-h/2,w,h);for(int i=0;i<n;i++){var point=g.Position(i);var info=point.x<.5f?new UnityEngine.Vector2(.115f,point.y):point.x>.5f?new UnityEngine.Vector2(.885f,point.y):new UnityEngine.Vector2(.78f,i==g.Start?.93f:.07f);reserved.Add(Box(info,142,66));reserved.Add(Box(point,38,38));}for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)if(g.Cost(a,b)>0){var box=Box(ForgeCoolingDiagram.CostLabelPosition(g,a,b),108,30);Require(!reserved.Any(r=>r.Overlaps(box)),"label overlap n="+n+" edge="+a+"-"+b);reserved.Add(box);}}});
 test("combined star and frost effects survive path cooling",()=>{var e=BlueprintRuntime.Evaluate("p=1(7)\n2(p)\n3(p)\n4(p,8)\n!p",0,0,"star frost",1,new Dictionary<int,long>{{7,1},{8,100}},context:new ForgeRunContext{CoolingUnlocked=true});Ok(e);Require(e.product.Data.star&&e.product.Data.frost&&e.product.Data.starlight.Initial.Count==5,"combined effects");Require(Used(e)==e.product.Data.cooling.PathCost(e.product.Data.cooling.DefaultPath()),"route debit");});
 test("guide contains all rules and basic/advanced split",()=>{foreach(string word in new[]{"80(Blade)","81(Blade)","82(Blade)","83(Blade, A, B)","84(Blade, FrostWater, Path)","[0, 1, 3]","[0, 2, 3]","첫 통로가 저렴하더라도","코드의 방문 표시","128","중단점","연습 초기화","심화"})Require(ForgeCoolingGuide.Basic.Contains(word),word);Require(!ForgeCoolingGuide.Basic.Contains("Distance = []")&&ForgeCoolingGuide.FullExample.Contains("Path = Reverse[::-1]"),"advanced hidden until selected");});
 return log.AppendLine("Cooling checks passed: "+count).ToString();
 }
}
